import json
with open('DATA/products/CoachForce.json') as f:
    data = json.load(f)

# Check the full MRR content for any "reviewer" mentions
for d in data['documents']:
    if d['type'] == 'Market Research Report':
        content = d['content']
        # Find any references to specific people or roles
        if 'reviewed by' in content.lower() or 'reviewed' in content.lower() or 'reviewer' in content.lower():
            print(f'{d["id"]}: contains review-related text')
            for line in content.split('\n'):
                if 'reviewed' in line.lower() or 'reviewer' in line.lower():
                    print(f'  {line}')

# Check if there's any other source indicating reviewers
# Check meeting transcripts document types
for t in data['meeting_transcripts']:
    print(f'Meeting: {t["id"]}, Type: {t["document_type"]}')
EOF

